package solution

import (
	"encoding/hex"
	"strings"
	"testing"
)

func requireDigestFormat(t *testing.T, digest string) {
	t.Helper()
	if len(digest) != 64 {
		t.Fatalf("digest length=%d, want 64: %q", len(digest), digest)
	}
	if digest != strings.ToLower(digest) {
		t.Fatalf("digest is not lowercase: %q", digest)
	}
	decoded, err := hex.DecodeString(digest)
	if err != nil || len(decoded) != 32 {
		t.Fatalf("digest is not a SHA-256 hex encoding: %q (%v)", digest, err)
	}
}

func TestRevisionGraphGenesisAndInitialRevisions(t *testing.T) {
	graph := NewRevisionGraph()
	if graph == nil {
		t.Fatal("NewRevisionGraph returned nil")
	}
	genesis := graph.Genesis()
	if len(genesis.Parents) != 0 || len(genesis.Edits) != 0 {
		t.Fatalf("genesis contains parents or edits: %+v", genesis)
	}
	requireDigestFormat(t, genesis.Digest)

	revisions := graph.Revisions()
	if len(revisions) != 1 {
		t.Fatalf("initial revision count=%d, want 1", len(revisions))
	}
	if revisions[0].Digest != genesis.Digest || len(revisions[0].Parents) != 0 || len(revisions[0].Edits) != 0 {
		t.Fatalf("initial revision is not genesis: %+v", revisions[0])
	}
}

func TestRevisionGraphAddPreservesOrderAndCopiesInputs(t *testing.T) {
	graph := NewRevisionGraph()
	genesis := graph.Genesis()
	parents := []string{genesis.Digest}
	edits := []Edit{{Path: "a.txt", Content: "first"}, {Path: "", Content: ""}, {Path: "b.txt", Content: "second"}}

	revision, err := graph.Add(parents, edits)
	if err != nil {
		t.Fatalf("Add returned error: %v", err)
	}
	requireDigestFormat(t, revision.Digest)
	if len(revision.Parents) != 1 || revision.Parents[0] != genesis.Digest {
		t.Fatalf("parents not preserved: %v", revision.Parents)
	}
	if len(revision.Edits) != len(edits) {
		t.Fatalf("edit count=%d, want %d", len(revision.Edits), len(edits))
	}
	for i := range edits {
		if revision.Edits[i] != edits[i] {
			t.Fatalf("edit %d=%+v, want %+v", i, revision.Edits[i], edits[i])
		}
	}

	parents[0] = "caller-mutated"
	edits[0] = Edit{Path: "changed", Content: "changed"}
	stored := graph.Revisions()
	if len(stored) != 2 {
		t.Fatalf("revision count=%d, want 2", len(stored))
	}
	if stored[1].Parents[0] != genesis.Digest || stored[1].Edits[0] != (Edit{Path: "a.txt", Content: "first"}) {
		t.Fatalf("stored revision aliases Add inputs: %+v", stored[1])
	}
}

func TestRevisionGraphReturnsDeepCopies(t *testing.T) {
	graph := NewRevisionGraph()
	genesis := graph.Genesis()
	added, err := graph.Add([]string{genesis.Digest}, []Edit{{Path: "file", Content: "content"}})
	if err != nil {
		t.Fatal(err)
	}

	added.Parents[0] = "changed-return-parent"
	added.Edits[0].Path = "changed-return-edit"
	firstRead := graph.Revisions()
	firstRead[1].Parents[0] = "changed-list-parent"
	firstRead[1].Edits[0].Content = "changed-list-edit"
	firstRead[1].Digest = "changed-digest"

	secondRead := graph.Revisions()
	if secondRead[1].Parents[0] != genesis.Digest {
		t.Fatalf("stored parent was mutated: %q", secondRead[1].Parents[0])
	}
	if secondRead[1].Edits[0] != (Edit{Path: "file", Content: "content"}) {
		t.Fatalf("stored edit was mutated: %+v", secondRead[1].Edits[0])
	}
	requireDigestFormat(t, secondRead[1].Digest)

	genesisCopy := graph.Genesis()
	genesisCopy.Digest = "changed"
	if graph.Genesis().Digest != genesis.Digest {
		t.Fatal("Genesis return value aliases graph storage")
	}
}

func TestRevisionGraphRejectsInvalidParentsWithoutMutation(t *testing.T) {
	graph := NewRevisionGraph()
	genesis := graph.Genesis()
	cases := []struct {
		name    string
		parents []string
	}{
		{name: "nil", parents: nil},
		{name: "empty slice", parents: []string{}},
		{name: "empty digest", parents: []string{""}},
		{name: "unknown", parents: []string{strings.Repeat("a", 64)}},
		{name: "duplicate", parents: []string{genesis.Digest, genesis.Digest}},
		{name: "valid plus empty", parents: []string{genesis.Digest, ""}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			before := len(graph.Revisions())
			if _, err := graph.Add(tc.parents, []Edit{{Path: "x", Content: "y"}}); err == nil {
				t.Fatal("Add unexpectedly succeeded")
			}
			if after := len(graph.Revisions()); after != before {
				t.Fatalf("invalid Add changed revision count from %d to %d", before, after)
			}
		})
	}
}

func TestRevisionDigestReflectsOrderedContentAndIsStable(t *testing.T) {
	graph := NewRevisionGraph()
	genesis := graph.Genesis()

	one, err := graph.Add([]string{genesis.Digest}, []Edit{{Path: "ab", Content: "c"}})
	if err != nil {
		t.Fatal(err)
	}
	two, err := graph.Add([]string{genesis.Digest}, []Edit{{Path: "a", Content: "bc"}})
	if err != nil {
		t.Fatal(err)
	}
	three, err := graph.Add([]string{genesis.Digest}, []Edit{{Path: "c", Content: "3"}, {Path: "d", Content: "4"}})
	if err != nil {
		t.Fatal(err)
	}
	four, err := graph.Add([]string{genesis.Digest}, []Edit{{Path: "d", Content: "4"}, {Path: "c", Content: "3"}})
	if err != nil {
		t.Fatal(err)
	}
	if one.Digest == two.Digest {
		t.Fatal("ambiguous path/content boundaries produced the same digest")
	}
	if three.Digest == four.Digest {
		t.Fatal("edit order did not affect digest")
	}

	other := NewRevisionGraph()
	otherGenesis := other.Genesis()
	matching, err := other.Add([]string{otherGenesis.Digest}, []Edit{{Path: "ab", Content: "c"}})
	if err != nil {
		t.Fatal(err)
	}
	if otherGenesis.Digest != genesis.Digest || matching.Digest != one.Digest {
		t.Fatal("equivalent graph operations produced unstable digests")
	}
}

package solution

import "testing"

func TestReviewRevisionFraming0228(t *testing.T) {
	build := func() (*RevisionGraph, []string) {
		g := NewRevisionGraph()
		root := g.Genesis().Digest
		a, err := g.Add([]string{root}, []Edit{{Path:"a",Content:"one"}})
		if err != nil { t.Fatal(err) }
		b, err := g.Add([]string{root}, []Edit{{Path:"b",Content:"two"}})
		if err != nil { t.Fatal(err) }
		return g, []string{root,a.Digest,b.Digest}
	}
	g1, parents := build()
	first, err := g1.Add(parents, nil)
	if err != nil { t.Fatal(err) }
	g2, sameParents := build()
	second, err := g2.Add(sameParents[:1], []Edit{{Path:sameParents[1],Content:sameParents[2]}})
	if err != nil { t.Fatal(err) }
	if first.Digest == second.Digest {
		t.Fatalf("three parents/no edits and one parent/one edit have identical digest: %s", first.Digest)
	}
}

